1	// Plain (non-"use server") module for the growth engine: constants, env getters
2	// and pure helpers shared by server actions and pages. Safe to import from any
3	// server module. Do NOT import this from client components — it pulls in `crypto`.
4	
5	import { randomInt } from "crypto";
6	import type { CouponKind } from "@prisma/client";
7	
8	/**
9	 * Reward (in cents) granted to BOTH the referrer and the referred user when the
10	 * referred user completes their first successful paid action. Env override:
11	 * REFERRAL_REWARD_CENTS. Defaults to 500 ($5.00).
12	 */
13	export function referralRewardCents(): number {
14	  const n = Number(process.env.REFERRAL_REWARD_CENTS);
15	  return Number.isFinite(n) && n >= 0 ? Math.round(n) : 500;
16	}
17	
18	/**
19	 * Free wallet credit (in cents) granted on signup. Env override:
20	 * SIGNUP_FREE_CREDIT_CENTS. Defaults to 0 (feature off).
21	 */
22	export function signupFreeCreditCents(): number {
23	  const n = Number(process.env.SIGNUP_FREE_CREDIT_CENTS);
24	  return Number.isFinite(n) && n >= 0 ? Math.round(n) : 0;
25	}
26	
27	// Unambiguous alphabet (no 0/O/1/I/L) for human-shareable referral codes.
28	const CODE_ALPHABET = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";
29	
30	/** Generate a random, unambiguous referral code (uppercase). Uniqueness must be
31	 *  enforced by the caller against the DB. */
32	export function generateReferralCode(length = 7): string {
33	  let out = "";
34	  for (let i = 0; i < length; i++) out += CODE_ALPHABET[randomInt(CODE_ALPHABET.length)];
35	  return out;
36	}
37	
38	/** Result of validating a promo code for a top-up (see applyCouponToTopup). */
39	export type CouponApplyResult =
40	  | {
41	      ok: true;
42	      couponId: string;
43	      code: string;
44	      /** Extra wallet credit (in cents) the user receives on top of the amount added. */
45	      bonusCents: number;
46	      /** Human-readable summary, e.g. "20% bonus". */
47	      label: string;
48	    }
49	  | { ok: false; error: string };
50	
51	/** Human-readable summary of what a coupon grants, e.g. "20% bonus", "$5.00 credit". */
52	export function describeCoupon(coupon: { kind: CouponKind; value: number }): string {
53	  switch (coupon.kind) {
54	    case "PERCENT":
55	      return `${coupon.value}% bonus`;
56	    case "FIXED_CENTS":
57	      return `$${(coupon.value / 100).toFixed(2)} off`;
58	    case "CREDIT_CENTS":
59	      return `$${(coupon.value / 100).toFixed(2)} credit`;
60	    default:
61	      return "discount";
62	  }
63	}
