1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { PageHeader, fmtMoney } from "@/components/ui/primitives";
4	import { ReferralPanel } from "@/components/customer/ReferralPanel";
5	import { referralRewardCents, generateReferralCode } from "@/lib/growth";
