221	/**
222	 * If `userId` was referred and hasn't been rewarded yet, credit BOTH the referred
223	 * user and their referrer with REFERRAL_REWARD_CENTS, exactly once. Guarded by an
224	 * atomic claim on `referralRewardedAt` so concurrent paid actions can't double-pay.
225	 * Callable from `topUp` / `orderServer` in lib/actions.ts after a paid action.
226	 */
227	export async function maybeRewardReferral(userId: string): Promise<boolean> {
228	  const reward = referralRewardCents();
229	  if (reward <= 0) return false;
230	
231	  const user = await db.user.findUnique({ where: { id: userId } });
232	  if (!user || !user.referredById || user.referralRewardedAt) return false;
233	  const referrerId = user.referredById;
234	
235	  // Atomically claim the reward; if another concurrent action already did, bail.
236	  const claim = await db.user.updateMany({
237	    where: { id: userId, referralRewardedAt: null, referredById: { not: null } },
238	    data: { referralRewardedAt: new Date() },
239	  });
240	  if (claim.count === 0) return false;
241	
242	  await db.$transaction([
243	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: reward } } }),
244	    db.walletTransaction.create({
245	      data: { userId, amountCents: reward, description: "Referral bonus — welcome reward" },
246	    }),
247	    db.user.update({ where: { id: referrerId }, data: { balanceCents: { increment: reward } } }),
248	    db.walletTransaction.create({
249	      data: {
250	        userId: referrerId,
251	        amountCents: reward,
252	        description: "Referral bonus — you referred a friend",
253	      },
254	    }),
255	  ]);
256	
257	  // Best-effort in-app notifications.
258	  try {
259	    await db.notification.createMany({
260	      data: [
261	        {
262	          userId,
263	          title: `You earned a $${(reward / 100).toFixed(2)} referral bonus`,
264	          href: "/dashboard/billing",
