// Tax/VAT + multi-currency DISPLAY helpers.
//
// Plain (non-"use server") module: exports pure helpers alongside async getters
// that read the `Setting` store. Safe to import from server components, server
// actions, the worker and (the pure parts) client components. Money is always
// integer cents.
//
// IMPORTANT — multi-currency here is DISPLAY ONLY. `formatMoney` swaps the symbol
// and code for the configured `currency` Setting; it performs NO FX conversion,
// so the underlying cents are unchanged. Do not use this to bill in a foreign
// currency. Tax helpers likewise compute a display/quote breakdown; wiring them
// into the actual charge path is an integration step owned by the billing flow.

import { getSetting } from "./settings";

// ---------------- Currency (display only) ----------------

export type CurrencyMeta = { symbol: string; code: string };

/** Symbol/code map for the currencies we can DISPLAY. No FX rates — display only. */
export const CURRENCIES: Record<string, CurrencyMeta> = {
  USD: { symbol: "$", code: "USD" },
  EUR: { symbol: "€", code: "EUR" },
  GBP: { symbol: "£", code: "GBP" },
  CAD: { symbol: "CA$", code: "CAD" },
  AUD: { symbol: "A$", code: "AUD" },
  NZD: { symbol: "NZ$", code: "NZD" },
  INR: { symbol: "₹", code: "INR" },
  JPY: { symbol: "¥", code: "JPY" },
  CNY: { symbol: "¥", code: "CNY" },
  BRL: { symbol: "R$", code: "BRL" },
  ZAR: { symbol: "R", code: "ZAR" },
  CHF: { symbol: "CHF ", code: "CHF" },
  SEK: { symbol: "kr ", code: "SEK" },
  PLN: { symbol: "zł ", code: "PLN" },
  MXN: { symbol: "MX$", code: "MXN" },
  SGD: { symbol: "S$", code: "SGD" },
  AED: { symbol: "د.إ ", code: "AED" },
};

export const DEFAULT_CURRENCY = "USD";

/** Resolve a currency code to its symbol/code. Unknown codes fall back to `CODE `. */
export function currencyMeta(code: string | undefined | null): CurrencyMeta {
  const key = (code ?? "").trim().toUpperCase();
  return CURRENCIES[key] ?? { symbol: key ? `${key} ` : "$", code: key || DEFAULT_CURRENCY };
}

/**
 * Format integer cents for DISPLAY in the given currency (default USD). Pure and
 * synchronous so client components can use it. No FX conversion is performed —
 * the numeric value is the same regardless of currency; only the symbol changes.
 */
export function formatMoney(cents: number, currencyCode: string = DEFAULT_CURRENCY): string {
  const { symbol } = currencyMeta(currencyCode);
  const n = Number.isFinite(cents) ? cents : 0;
  const sign = n < 0 ? "-" : "";
  const value = (Math.abs(n) / 100).toFixed(2);
  return `${sign}${symbol}${value}`;
}

/** The configured display currency code (reads the `currency` Setting). */
export async function currentCurrency(): Promise<string> {
  const raw = (await getSetting("currency")).trim().toUpperCase();
  return raw || DEFAULT_CURRENCY;
}

// ---------------- Tax / VAT ----------------

export type TaxBreakdown = { net: number; tax: number; total: number };

/** The configured tax/VAT rate as a percent number (reads the `tax_percent` Setting). */
export async function taxRate(): Promise<number> {
  const n = Number(await getSetting("tax_percent"));
  return Number.isFinite(n) && n > 0 ? n : 0;
}

/**
 * Split a net (pre-tax) amount in cents into { net, tax, total }. Pure — pass the
 * rate (e.g. from `taxRate()`); the tax is rounded to the nearest cent. A rate of
 * 0 yields tax 0 and total === net.
 */
export function applyTax(cents: number, ratePercent: number = 0): TaxBreakdown {
  const net = Math.max(0, Math.round(Number.isFinite(cents) ? cents : 0));
  const rate = Number.isFinite(ratePercent) && ratePercent > 0 ? ratePercent : 0;
  const tax = Math.round((net * rate) / 100);
  return { net, tax, total: net + tax };
}

/** Async convenience: read the configured rate and apply it in one call. */
export async function applyTaxFromSettings(cents: number): Promise<TaxBreakdown> {
  return applyTax(cents, await taxRate());
}

// Affiliate program logic — tier constants + earnings/payout computation.
//
// Plain (non-"use server") module: exports constants and (db-backed) computation
// helpers used by the affiliate pages and server actions. Not for client import.
//
// Accounting model
// ----------------
// The existing referral engine (lib/actions-growth.ts → maybeRewardReferral)
// already credits a referrer's WALLET when a person they referred makes their
// first payment, writing a ledger row with the description below. That ledger is
// our source of truth for "total affiliate earnings". Payout requests draw
// against those earnings and are tracked separately in AffiliatePayout — a payout
// is a MANUAL cash-out handled by an admin, it does NOT debit the wallet here.
//
// available = totalEarned − (PENDING + APPROVED + PAID payouts)   [DECLINED ignored]

import { db } from "./db";

/** Exact WalletTransaction.description written for the referrer's reward (see
 *  lib/actions-growth.ts). Used to total affiliate earnings from the ledger. */
export const REFERRAL_EARNING_DESCRIPTION = "Referral bonus — you referred a friend";

/** Minimum balance (cents) a customer must have available to request a payout. */
export const MIN_PAYOUT_CENTS = 2500; // $25.00

/** Payout lifecycle statuses (mirrors AffiliatePayout.status). */
export const PAYOUT_STATUSES = ["PENDING", "APPROVED", "PAID", "DECLINED"] as const;
export type PayoutStatus = (typeof PAYOUT_STATUSES)[number];

/**
 * Commission tiers. `perReferralCents` is what the marketing copy advertises a
 * paying referral is worth once you reach `minReferrals` paying referrals — an
 * escalating incentive. (The wallet credit actually paid per referral is governed
 * by the `referral_reward_cents` Setting / REFERRAL_REWARD_CENTS in the growth
 * engine; these tiers are the customer-facing program description.)
 */
export const AFFILIATE_TIERS = [
  { name: "Starter", minReferrals: 0, perReferralCents: 500 },
  { name: "Pro", minReferrals: 5, perReferralCents: 800 },
  { name: "Elite", minReferrals: 15, perReferralCents: 1200 },
] as const;

export type AffiliateTier = (typeof AFFILIATE_TIERS)[number];

/** The tier a customer currently sits in given their paying-referral count. */
export function currentTier(payingReferrals: number): AffiliateTier {
  let tier: AffiliateTier = AFFILIATE_TIERS[0];
  for (const t of AFFILIATE_TIERS) {
    if (payingReferrals >= t.minReferrals) tier = t;
  }
  return tier;
}

/** The next tier up (null if already at the top), for "N more to unlock…" copy. */
export function nextTier(payingReferrals: number): AffiliateTier | null {
  return AFFILIATE_TIERS.find((t) => t.minReferrals > payingReferrals) ?? null;
}

export type AffiliateEarnings = {
  referredCount: number;
  payingCount: number;
  totalEarnedCents: number;
  pendingPayoutCents: number; // PENDING + APPROVED (in-flight, not yet cashed out)
  paidPayoutCents: number; // PAID
  availableCents: number; // totalEarned − (pending + approved + paid)
  tier: AffiliateTier;
  next: AffiliateTier | null;
  canRequestPayout: boolean;
};

/**
 * Compute a customer's affiliate standing: referral counts, lifetime earnings
 * (from the wallet ledger) and how much is still available to cash out after
 * subtracting non-declined payouts.
 */
export async function computeAffiliateEarnings(userId: string): Promise<AffiliateEarnings> {
  const [referredCount, payingCount, earnedAgg, payouts] = await Promise.all([
    db.user.count({ where: { referredById: userId } }),
    db.user.count({ where: { referredById: userId, referralRewardedAt: { not: null } } }),
    db.walletTransaction.aggregate({
      _sum: { amountCents: true },
      where: { userId, description: REFERRAL_EARNING_DESCRIPTION },
    }),
    db.affiliatePayout.findMany({
      where: { userId, status: { not: "DECLINED" } },
      select: { amountCents: true, status: true },
    }),
  ]);

  const totalEarnedCents = earnedAgg._sum.amountCents ?? 0;
  let pendingPayoutCents = 0;
  let paidPayoutCents = 0;
  for (const p of payouts) {
    if (p.status === "PAID") paidPayoutCents += p.amountCents;
    else pendingPayoutCents += p.amountCents; // PENDING or APPROVED
  }

  const availableCents = Math.max(0, totalEarnedCents - pendingPayoutCents - paidPayoutCents);

  return {
    referredCount,
    payingCount,
    totalEarnedCents,
    pendingPayoutCents,
    paidPayoutCents,
    availableCents,
    tier: currentTier(payingCount),
    next: nextTier(payingCount),
    canRequestPayout: availableCents >= MIN_PAYOUT_CENTS,
  };
}

"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";
import {
  computeAffiliateEarnings,
  MIN_PAYOUT_CENTS,
  PAYOUT_STATUSES,
  type PayoutStatus,
} from "./affiliate";

// ---------- Customer: request a payout ----------

/**
 * Request an affiliate payout for `amountCents`. Guards:
 *  - integer cents ≥ MIN_PAYOUT_CENTS ($25)
 *  - amount ≤ the caller's currently AVAILABLE affiliate balance (earnings minus
 *    any non-declined payouts). Availability is recomputed server-side inside the
 *    request so a stale client can't over-draw.
 * Creates a PENDING AffiliatePayout. Cash-out itself is manual (admin-processed).
 */
export async function requestAffiliatePayout(
  amountCents: number
): Promise<{ ok?: boolean; error?: string }> {
  const user = await requireUser();

  const cents = Math.round(Number(amountCents));
  if (!Number.isFinite(cents) || cents <= 0) {
    return { error: "Enter a valid amount." };
  }
  if (cents < MIN_PAYOUT_CENTS) {
    return { error: `Minimum payout is $${(MIN_PAYOUT_CENTS / 100).toFixed(2)}.` };
  }

  const earnings = await computeAffiliateEarnings(user.id);
  if (cents > earnings.availableCents) {
    return {
      error: `You only have $${(earnings.availableCents / 100).toFixed(2)} available to withdraw.`,
    };
  }

  await db.affiliatePayout.create({
    data: { userId: user.id, amountCents: cents, status: "PENDING" },
  });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "affiliate.payout_request",
      detail: `$${(cents / 100).toFixed(2)}`,
    },
  });

  revalidatePath("/dashboard/affiliate");
  return { ok: true };
}

// ---------- Admin: update a payout's status ----------

const ALLOWED: readonly PayoutStatus[] = PAYOUT_STATUSES;

/**
 * Move a payout request to APPROVED / PAID / DECLINED. On PAID we stamp `paidAt`
 * to record the cash-out; other transitions clear it. Billing-area gated.
 */
export async function adminUpdatePayout(
  id: string,
  status: string
): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireArea("billing");

  if (!ALLOWED.includes(status as PayoutStatus)) {
    return { error: "Invalid status." };
  }
  const payout = await db.affiliatePayout.findUnique({ where: { id } });
  if (!payout) return { error: "Payout not found." };

  await db.affiliatePayout.update({
    where: { id },
    data: {
      status,
      paidAt: status === "PAID" ? new Date() : null,
    },
  });
  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: "affiliate.payout_update",
      detail: `${payout.id} → ${status} ($${(payout.amountCents / 100).toFixed(2)})`,
    },
  });

  revalidatePath("/admin/affiliate");
  return { ok: true };
}

// Reusable, presentational tax/VAT breakdown line.
//
// Pure (no "use client", no async, no DB): pass the net amount in cents, the tax
// rate as a percent, and the display currency code. Renders Subtotal / Tax /
// Total rows using lib/tax helpers. Callers that need the live rate/currency read
// them from Settings (taxRate(), currentCurrency()) and pass them in — keeping
// this component usable from both server and client trees.
//
// Multi-currency is DISPLAY ONLY (no FX). When taxPercent is 0 the tax row is
// hidden and only the total is shown.

import { applyTax, formatMoney } from "@/lib/tax";

export function TaxLine({
  netCents,
  taxPercent = 0,
  currency = "USD",
  totalLabel = "Total",
  taxLabel = "VAT / Tax",
  netLabel = "Subtotal",
  className = "",
}: {
  netCents: number;
  taxPercent?: number;
  currency?: string;
  totalLabel?: string;
  taxLabel?: string;
  netLabel?: string;
  className?: string;
}) {
  const { net, tax, total } = applyTax(netCents, taxPercent);
  const showTax = taxPercent > 0;

  return (
    <div className={`space-y-1.5 text-sm ${className}`}>
      {showTax && (
        <>
          <div className="flex items-center justify-between text-slate-400">
            <span>{netLabel}</span>
            <span className="font-mono">{formatMoney(net, currency)}</span>
          </div>
          <div className="flex items-center justify-between text-slate-400">
            <span>
              {taxLabel} <span className="text-slate-500">({taxPercent}%)</span>
            </span>
            <span className="font-mono">{formatMoney(tax, currency)}</span>
          </div>
        </>
      )}
      <div className="flex items-center justify-between border-t border-white/[0.06] pt-1.5 font-semibold text-slate-100">
        <span>{totalLabel}</span>
        <span className="font-mono">{formatMoney(total, currency)}</span>
      </div>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { requestAffiliatePayout, adminUpdatePayout } from "@/lib/actions-affiliate";

// ---------- Customer: request a payout ----------

/**
 * Payout request form for the customer affiliate page. `availableCents` and
 * `minCents` come from the server (lib/affiliate); the amount defaults to the
 * full available balance. The server action re-validates the guard regardless of
 * what's posted here.
 */
export function PayoutRequestForm({
  availableCents,
  minCents,
  currency = "USD",
}: {
  availableCents: number;
  minCents: number;
  currency?: string;
}) {
  const [amount, setAmount] = useState<string>((availableCents / 100).toFixed(2));
  const [msg, setMsg] = useState<{ ok?: boolean; error?: string } | null>(null);
  const [pending, start] = useTransition();

  const eligible = availableCents >= minCents;

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    setMsg(null);
    const cents = Math.round(Number(amount) * 100);
    if (!Number.isFinite(cents) || cents <= 0) {
      setMsg({ error: "Enter a valid amount." });
      return;
    }
    start(async () => {
      const res = await requestAffiliatePayout(cents);
      setMsg(res);
    });
  };

  if (!eligible) {
    return (
      <p className="text-sm text-slate-400">
        You need at least{" "}
        <span className="font-semibold text-slate-200">${(minCents / 100).toFixed(2)}</span>{" "}
        available to request a payout. Keep referring to reach the threshold.
      </p>
    );
  }

  return (
    <form onSubmit={submit} className="space-y-3">
      {msg?.error && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {msg.error}
        </div>
      )}
      {msg?.ok && (
        <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
          Payout requested — we&apos;ll review and process it shortly.
        </div>
      )}
      <div className="flex flex-wrap items-end gap-2">
        <div>
          <label className="label">Amount ({currency})</label>
          <input
            className="input w-36"
            type="number"
            min={(minCents / 100).toFixed(2)}
            max={(availableCents / 100).toFixed(2)}
            step="0.01"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
          />
        </div>
        <button className="btn-primary" disabled={pending}>
          {pending ? "Requesting…" : "Request payout"}
        </button>
      </div>
      <p className="text-[11px] text-slate-500">
        Minimum ${(minCents / 100).toFixed(2)}. Available ${(availableCents / 100).toFixed(2)}.
        Payouts are reviewed and paid manually.
      </p>
    </form>
  );
}

// ---------- Admin: payout status controls ----------

const NEXT_ACTIONS: Record<string, { label: string; status: string; cls: string }[]> = {
  PENDING: [
    { label: "Approve", status: "APPROVED", cls: "btn-secondary" },
    { label: "Decline", status: "DECLINED", cls: "btn-danger" },
  ],
  APPROVED: [
    { label: "Mark paid", status: "PAID", cls: "btn-primary" },
    { label: "Decline", status: "DECLINED", cls: "btn-danger" },
  ],
  DECLINED: [{ label: "Reopen", status: "PENDING", cls: "btn-secondary" }],
  PAID: [],
};

export function PayoutStatusControls({ id, status }: { id: string; status: string }) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const actions = NEXT_ACTIONS[status] ?? [];

  if (actions.length === 0) {
    return <span className="text-xs text-slate-500">—</span>;
  }

  const run = (next: string, confirmMsg?: string) => {
    if (confirmMsg && !confirm(confirmMsg)) return;
    setError(null);
    start(async () => {
      const res = await adminUpdatePayout(id, next);
      if (res?.error) setError(res.error);
    });
  };

  return (
    <div className="flex flex-col items-end gap-1">
      <div className="flex items-center justify-end gap-1">
        {actions.map((a) => (
          <button
            key={a.status}
            className={`${a.cls} py-1 text-xs`}
            disabled={pending}
            onClick={() =>
              run(
                a.status,
                a.status === "PAID"
                  ? "Mark this payout as PAID? This records it as cashed out."
                  : a.status === "DECLINED"
                    ? "Decline this payout request?"
                    : undefined
              )
            }
          >
            {a.label}
          </button>
        ))}
      </div>
      {error && <span className="text-[11px] text-red-400">{error}</span>}
    </div>
  );
}

